import {directions,gardenLessons,newGarden,cellName,addCommand,removeCommand,moveOne,resetRun,selectGardenPage,undoEdit,replaceCommand,clearCommands,previewNext} from './garden-game.mjs';
const labels={try:'Explora',plan:'Planea',change:'Ajusta',offscreen:'En papel'};
export function renderGarden(root,state,onFinish){
 state.garden??=newGarden();const game=state.garden;
 const draw=(focusId,announcement)=>{
  const lesson=gardenLessons.find(l=>l.id===game.page),route=lesson&&game.routes[lesson.id];
  if(route&&(!Number.isInteger(route.editIndex)||route.editIndex>=route.commands.length))route.editIndex=null;
  const preview=lesson?previewNext(route,lesson):null;
  const editing=route&&route.editIndex!==null;
  const stepLabel=route?.status==='blocked'?`Revisar paso ${route.cursor+1}`:route?.status==='arrived'?'Volver a probar':'Mover un paso';
  const prompt=!route?'':route.status==='arrived'?'Llegaste. ¿Cómo explicarías tu camino?':route.status==='blocked'?'Una parte del plan necesita cambiar.':editing?`Elige la nueva dirección del paso ${route.editIndex+1}.`:!route.commands.length?'Empieza con una flecha. Tú decides el camino.':route.cursor>=route.commands.length?'Puedes ampliar tu camino o revisar una flecha.':'Imagina dónde llegará Nilo. Después, prueba un paso.';
  root.innerHTML=`<section class="garden garden-studio" aria-label="Juego de programación de caminos">
   <nav class="garden-nav" aria-label="Partes del juego"><div>${[...gardenLessons.map(l=>l.id),'offscreen'].map((id,i)=>`<button type="button" class="garden-tab" data-garden-page="${id}" ${game.page===id?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${labels[id]}</button>`).join('')}</div></nav>
   ${lesson?`<header class="garden-heading"><div><p class="eyebrow">JARDÍN DE LOS CAMINOS · ${labels[lesson.id].toUpperCase()}</p><h5 id="garden-title" tabindex="-1">${lesson.title}</h5><p>${lesson.instruction}</p></div><button type="button" class="garden-help-button" id="garden-demo-toggle" aria-expanded="${!!game.demoOpen}" aria-controls="garden-demo">${game.demoOpen?'Cerrar ejemplo':'¿Cómo se juega?'}</button></header>
   <div id="garden-demo" class="garden-demo" ${game.demoOpen?'':'hidden'}><div><strong>Un ejemplo aparte, sin cambiar tu camino</strong><p>Una flecha es una casilla hacia ese lado del tablero. Dos flechas se prueban en orden.</p></div><div class="garden-demo-track" role="img" aria-label="Ejemplo: Nilo ${game.demoStep>0?'avanzó '+game.demoStep+' casillas a la derecha':'espera en el inicio'}.">${[0,1,2].map(i=>`<span>${(game.demoStep||0)===i?'<b class="nilo" aria-hidden="true"><i></i><i></i></b>':i===2?'✿':'·'}</span>`).join('')}</div><div class="garden-demo-code">→ <span>→</span></div><button type="button" class="action secondary" id="garden-demo-step">${game.demoStep>=2?'Repetir ejemplo':'Ver un paso del ejemplo'}</button><p class="quiet">Puedes cerrar el ejemplo cuando quieras. No tienes que copiarlo.</p></div>
   <div class="garden-tutorial" aria-label="Tu siguiente acción"><span aria-hidden="true">${route.status==='blocked'?'↺':route.status==='arrived'?'✿':editing?'↔':'→'}</span><p>${prompt}</p><small>Sin reloj · A tu ritmo</small></div>
   <div class="garden-workspace">
    <div class="garden-world">
     <div class="garden-world-bar"><span><i class="garden-key-dot"></i> Nilo · ${cellName(route.position)}</span><span>Flor · ${cellName(lesson.goal)}</span></div>
     <div class="garden-board" role="img" aria-label="Tablero de cuatro filas y cuatro columnas. Nilo en ${cellName(route.position)}. Flor en ${cellName(lesson.goal)}. ${lesson.walls.length?'Piedras en '+lesson.walls.map(cellName).join(', ')+'.':'Sin piedras.'} Las flechas indican lados fijos del tablero. Columnas A a D de izquierda a derecha; filas 1 a 4 de arriba abajo.">
     ${Array.from({length:16},(_,i)=>{const p=[i%4,Math.floor(i/4)],is=a=>a[0]===p[0]&&a[1]===p[1],robot=is(route.position),goal=is(lesson.goal),wall=lesson.walls.some(is),trail=route.trail.some(is),next=preview?.to&&is(preview.to);return `<div class="garden-cell ${wall?'garden-stone':goal?'garden-goal':trail?'garden-trail':''} ${next?'garden-next':''} ${next&&preview.blocked?'garden-next-blocked':''}" aria-hidden="true"><span class="garden-coordinate">${cellName(p)}</span>${robot?'<span class="nilo"><i></i><i></i></span>':wall?'<span class="garden-rock">◆</span>':goal?'<span class="garden-flower">✿</span>':trail?'<span class="garden-dot">·</span>':''}<span class="garden-cell-label">${robot?'Nilo':wall?'Piedra':goal?'Flor':p[0]===0&&p[1]===3?'Inicio':''}</span></div>`;}).join('')}</div>
     <div class="garden-board-caption"><span>Una flecha, una casilla</span><span>◎ Próximo destino</span></div>
     <div class="garden-run-row"><button type="button" class="action primary" id="garden-step"><span aria-hidden="true">${route.status==='blocked'?'↺':route.status==='arrived'?'↻':'▷'}</span>${stepLabel}</button><button type="button" class="garden-icon-button" id="garden-replay" aria-label="Volver al inicio conservando las flechas" title="Volver al inicio">↶</button></div>
     <div id="garden-status" class="garden-status ${route.status==='blocked'?'is-blocked':route.status==='arrived'?'is-arrived':''}" role="status" aria-live="polite" aria-atomic="true">${route.message||'Nilo espera tu primera instrucción.'}</div>
    </div>
    <div class="garden-program"><div class="garden-program-heading"><div><span class="eyebrow">TU PROGRAMA</span><h6>Un camino hecho por ti</h6></div><span class="garden-command-count" aria-label="${route.commands.length} flechas de un máximo de 12">${route.commands.length}/12</span></div>
     <p class="garden-edit-help">${editing?`Cambia el paso ${route.editIndex+1} con una flecha de abajo.`:'Añade flechas. Toca un paso del camino para cambiarlo.'}</p>
     <div class="garden-arrows" role="group" aria-label="${editing?'Cambiar movimiento':'Añadir movimientos'}">${['up','left','down','right'].map(id=>`<button type="button" id="garden-add-${id}" data-garden-add="${id}" aria-label="${editing?'Cambiar paso '+(route.editIndex+1)+' a':'Añadir'} ${directions[id].label.toLowerCase()}"><span aria-hidden="true">${directions[id].symbol}</span><small>${directions[id].label}</small></button>`).join('')}</div>
     <ol class="garden-sequence" aria-label="Camino construido">${route.commands.map((id,i)=>`<li><button type="button" id="garden-command-${i}" data-garden-select="${i}" aria-label="Editar paso ${i+1}: ${directions[id].label.toLowerCase()}" aria-pressed="${route.editIndex===i}" ${i===route.cursor&&route.status!=='arrived'?'aria-current="step"':''} class="${i<route.cursor?'garden-used':''}"><small>${i+1}</small><span aria-hidden="true">${directions[id].symbol}</span>${i===route.cursor&&route.status!=='arrived'?'<em>Sigue</em>':''}</button></li>`).join('')}</ol>
     ${!route.commands.length?'<div class="garden-empty"><span aria-hidden="true">↑ → ↓</span><p>Aquí empieza tu camino</p><small>Elige una flecha para empezar.</small></div>':''}
     ${editing?`<div class="garden-edit-panel"><span>Paso ${route.editIndex+1} seleccionado</span><button type="button" class="garden-text-button" id="garden-remove">Quitar este paso</button><button type="button" class="garden-text-button" id="garden-cancel-edit">Listo, seguir añadiendo</button></div>`:''}
     <div class="garden-edit-actions"><button type="button" class="garden-text-button" id="garden-undo" ${route.undo?'':'disabled'}>↶ Deshacer cambio</button><button type="button" class="garden-text-button" id="garden-clear" ${route.commands.length?'':'disabled'}>Borrar flechas</button></div>
     <p class="garden-reset-note">Al editar, Nilo vuelve al inicio para probar el plan nuevo. «Deshacer» recupera el cambio anterior.</p>
     <div class="garden-hint-box"><button type="button" class="garden-text-button" id="garden-hint">${route.hint===lesson.hints.length?'Releer la pista':route.hint?'Otra pista':'Una pista, si la necesitas'} <span aria-hidden="true">→</span></button><p id="garden-hint-text" role="status" aria-live="polite">${route.hint?lesson.hints[route.hint-1]:''}</p></div>
    </div>
   </div>
   ${route.status==='arrived'?`<div class="garden-reflection"><span class="eyebrow">TU IDEA IMPORTA</span><h6>${lesson.reflection}</h6><p>Puedes explicarlo hablando, señalando o dibujando. Una solución no es la única.</p><div class="controls"><button type="button" class="action primary" id="garden-finish">Terminar este juego</button><button type="button" class="action secondary" data-garden-page="${lesson.id==='try'?'plan':lesson.id==='plan'?'change':'offscreen'}">${lesson.id==='change'?'Si quieres: jugar en papel':'Si quieres: explorar otra parte'}</button></div></div>`:''}
   <details class="garden-coach"><summary><span>Para quien acompaña</span> Una ayuda breve, justo aquí</summary><p>${lesson.coach}</p><p>Puede señalar y otra persona pulsar. Describe lo que hizo y pregunta por su idea, sin atribuir capacidad a un acierto. Parar también es una opción.</p></details>
   `:`<div class="garden-offscreen"><p class="eyebrow">DEL TABLERO A TU MUNDO</p><h5 id="garden-title" tabindex="-1">Tu próximo jardín cabe en una hoja.</h5><p>Ahora inventas tú. Una persona puede dibujar y otra señalar; no hace falta copiar el tablero completo.</p><div class="garden-paper" aria-hidden="true"><span>Inicio</span><span>→</span><span>→</span><span>✿ Flor</span></div><div class="garden-paper-steps"><article><b>01</b><h6>Dibuja</h6><p>Marca un inicio, una flor y una piedra. Dos o tres casillas también sirven.</p></article><article><b>02</b><h6>Da instrucciones</h6><p>Otra persona sigue tu camino con un dedo, una casilla cada vez. ¿Llegó donde imaginabas?</p></article><article><b>03</b><h6>Cambia una cosa</h6><p>Mueve la piedra dibujada. Revisen el camino e intercambien quién inventa y quién prueba.</p></article></div><details class="garden-coach"><summary>Para quien acompaña: dar espacio para pensar</summary><p>Sigue su instrucción sin corregirla antes de probar. Si no llega, pregunta «¿qué paso quieres cambiar?». Ayuda con una sola casilla y retira la ayuda cuando ya no haga falta.</p></details><p class="quiet">Basta papel y conversar o señalar. No se necesitan piezas pequeñas ni caminar mirando la pantalla. No hay foto ni respuesta que enviar.</p><button type="button" class="action primary" id="garden-finish">Guardar la pantalla y jugar</button></div>`}
  </section>`;
  const bind=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>fn(el)));
  bind('[data-garden-page]',el=>{selectGardenPage(game,el.dataset.gardenPage);draw('garden-title');});
  if(lesson){
   bind('[data-garden-add]',el=>{if(editing){replaceCommand(route,route.editIndex,el.dataset.gardenAdd);route.editIndex=null;}else addCommand(route,el.dataset.gardenAdd);draw(el.id,route.message);});
   bind('[data-garden-select]',el=>{route.editIndex=Number(el.dataset.gardenSelect);draw(el.id,`Paso ${route.editIndex+1} seleccionado. Elige una dirección para cambiarlo o quita este paso.`);});
   bind('#garden-remove',()=>{removeCommand(route,route.editIndex);route.editIndex=null;draw('garden-add-up',route.message);});
   bind('#garden-cancel-edit',()=>{route.editIndex=null;draw('garden-add-up','Puedes seguir añadiendo flechas.');});
   bind('#garden-step',()=>{if(route.status==='blocked'){route.editIndex=route.cursor;draw(`garden-command-${route.cursor}`,'Seleccionamos el paso bloqueado. Elige una dirección para cambiarlo.');}else if(route.status==='arrived'){resetRun(route);draw('garden-step',route.message);}else {moveOne(route,lesson);draw('garden-step',route.message);}});
   bind('#garden-replay',()=>{resetRun(route);route.editIndex=null;draw('garden-replay',route.message);});
   bind('#garden-clear',()=>{clearCommands(route);route.editIndex=null;draw('garden-add-up',route.message);});
   bind('#garden-undo',()=>{undoEdit(route);route.editIndex=null;draw('garden-add-up',route.message);});
   bind('#garden-hint',()=>{route.hint=Math.min(route.hint+1,lesson.hints.length);draw('garden-hint',lesson.hints[route.hint-1]);});
   bind('#garden-demo-toggle',()=>{game.demoOpen=!game.demoOpen;draw('garden-demo-toggle');});
   bind('#garden-demo-step',()=>{game.demoStep=(game.demoStep||0)>=2?0:(game.demoStep||0)+1;draw('garden-demo-step',`Ejemplo: ${game.demoStep} pasos. Tu propio camino no cambia.`);});
  }
  bind('#garden-finish',onFinish);
  if(focusId)root.querySelector('#'+focusId)?.focus({preventScroll:true});
  if(announcement)document.querySelector('#app-status').textContent=announcement;
 };
 draw();
}
